(* A small vector-graphics scene model with integer coordinates. *)

type point = int * int

(* Stroke width and whether the shape is filled. *)
type style = int * bool

type shape =
  | Circle of point * int * style (* centre, radius *)
  | Rect of point * point * style (* any two opposite corners *)
  | Line of point * point * style (* endpoints *)

type scene = shape list

(* Integer area. A circle uses 22/7 as pi, so the result is exact
   for radii that are multiples of 7 and a floor otherwise.
   A rect's corners may be given in any order. A line has no area.
   Style does not affect area. *)
let area (s : shape) : int =
  match s with
  | Circle (_, r, _) -> 22 * r * r / 7
  | Rect ((x1, y1), (x2, y2), _) -> abs (x2 - x1) * abs (y2 - y1)
  | Line _ -> 0

(* Two styles used throughout the tests. *)
let thin : style = (1, false)
let filled : style = (3, true)

let%test "area of circle radius 7 is 154" =
  area (Circle ((0, 0), 7, thin)) = 154
let%test "area of circle radius 0 is 0" = area (Circle ((3, 4), 0, thin)) = 0
let%test "area of circle ignores centre" =
  area (Circle ((-5, 9), 14, thin)) = area (Circle ((0, 0), 14, thin))
let%test "area ignores style" =
  area (Circle ((0, 0), 7, thin)) = area (Circle ((0, 0), 7, filled))
  && area (Rect ((1, 1), (4, 3), thin)) = area (Rect ((1, 1), (4, 3), filled))

let%test "area of rect" = area (Rect ((1, 1), (4, 3), thin)) = 6
let%test "area of rect with corners in any order" =
  area (Rect ((4, 3), (1, 1), thin)) = 6 && area (Rect ((1, 3), (4, 1), thin)) = 6
let%test "area of degenerate rect is 0" = area (Rect ((2, 2), (2, 5), thin)) = 0
let%test "area of line is 0" = area (Line ((0, 0), (10, 10), filled)) = 0

(* Transforms. Each one, given its parameters, is scene -> scene.
   All of them preserve style. *)

(* Apply [f] to every point of a shape, leaving non-point data alone. *)
let map_points (f : point -> point) (s : shape) : shape =
  match s with
  | Circle (c, r, st) -> Circle (f c, r, st)
  | Rect (p, q, st) -> Rect (f p, f q, st)
  | Line (p, q, st) -> Line (f p, f q, st)

let translate ((dx, dy) : point) : scene -> scene =
  List.map (map_points (fun (x, y) -> (x + dx, y + dy)))

(* Mirror across the y axis: x becomes -x. *)
let flip_x : scene -> scene = List.map (map_points (fun (x, y) -> (-x, y)))

(* Scale about the origin by an integer factor. Radii stay non-negative,
   so a negative factor is a scale plus a point reflection. *)
let scale (k : int) : scene -> scene =
  let pt (x, y) = (k * x, k * y) in
  List.map (function
    | Circle (c, r, st) -> Circle (pt c, abs (k * r), st)
    | s -> map_points pt s)

(* A sample scene used by the transform and bbox tests. *)
let sample : scene =
  [ Circle ((0, 0), 7, filled);
    Rect ((1, 1), (4, 3), thin);
    Line ((-2, 5), (6, -1), (2, false)) ]

let areas (sc : scene) : int list = List.map area sc

let style_of (s : shape) : style =
  match s with Circle (_, _, st) | Rect (_, _, st) | Line (_, _, st) -> st

let styles (sc : scene) : style list = List.map style_of sc

let%test "translate moves every point" =
  translate (10, -3) sample
  = [ Circle ((10, -3), 7, filled);
      Rect ((11, -2), (14, 0), thin);
      Line ((8, 2), (16, -4), (2, false)) ]
let%test "translate by (0,0) is the identity" = translate (0, 0) sample = sample
let%test "translate of empty scene is empty" = translate (5, 5) [] = []
let%test "translate preserves area" =
  areas (translate (3, 9) sample) = areas sample
let%test "translate preserves style" =
  styles (translate (3, 9) sample) = styles sample

let%test "flip_x negates x only" =
  flip_x sample
  = [ Circle ((0, 0), 7, filled);
      Rect ((-1, 1), (-4, 3), thin);
      Line ((2, 5), (-6, -1), (2, false)) ]
let%test "flip_x twice is the identity" = flip_x (flip_x sample) = sample
let%test "flip_x preserves area" = areas (flip_x sample) = areas sample
let%test "flip_x preserves style" = styles (flip_x sample) = styles sample

