  scale (-3) [ Circle ((1, 2), 5, thin) ] = [ Circle ((-3, -6), 15, thin) ]
let%test "scale by k multiplies rect area by k squared" =
  area (List.nth (scale 3 sample) 1) = 9 * area (List.nth sample 1)
let%test "scale preserves style" = styles (scale 4 sample) = styles sample

(* Bounding boxes, as (lower-left, upper-right). Style is ignored:
   the box is of the geometry, not the stroke. *)

let bbox_shape (s : shape) : point * point =
  match s with
  | Circle ((cx, cy), r, _) -> ((cx - r, cy - r), (cx + r, cy + r))
  | Rect ((x1, y1), (x2, y2), _) | Line ((x1, y1), (x2, y2), _) ->
      ((min x1 x2, min y1 y2), (max x1 x2, max y1 y2))

(* The smallest box containing every shape. The empty scene has the
   degenerate box ((0, 0), (0, 0)). *)
let bbox (sc : scene) : point * point =
  match List.map bbox_shape sc with
  | [] -> ((0, 0), (0, 0))
  | b :: bs ->
      List.fold_left
        (fun ((lx, ly), (hx, hy)) ((lx', ly'), (hx', hy')) ->
          ((min lx lx', min ly ly'), (max hx hx', max hy hy')))
        b bs

let%test "bbox of empty scene is degenerate at origin" =
  bbox [] = ((0, 0), (0, 0))
let%test "bbox of a circle" =
  bbox [ Circle ((3, -2), 5, thin) ] = ((-2, -7), (8, 3))
let%test "bbox of a rect normalises corners" =
  bbox [ Rect ((4, 1), (1, 3), thin) ] = ((1, 1), (4, 3))
let%test "bbox of a line" =
  bbox [ Line ((-2, 5), (6, -1), thin) ] = ((-2, -1), (6, 5))
let%test "bbox ignores style" =
  bbox [ Circle ((3, -2), 5, (9, true)) ] = bbox [ Circle ((3, -2), 5, thin) ]
let%test "bbox of the sample scene" = bbox sample = ((-7, -7), (7, 7))
let%test "bbox grows to cover a far shape" =
  bbox (Line ((20, 20), (21, 21), thin) :: sample) = ((-7, -7), (21, 21))
let%test "bbox commutes with translate" =
  let ((lx, ly), (hx, hy)) = bbox sample in
  bbox (translate (10, -3) sample) = ((lx + 10, ly - 3), (hx + 10, hy - 3))
let%test "bbox of flip_x mirrors the x range" =
  let sc = Rect ((1, 2), (9, 4), thin) :: sample in
  let ((lx, ly), (hx, hy)) = bbox sc in
  bbox (flip_x sc) = ((-hx, ly), (-lx, hy))
let%test "bbox of scale scales the box" =
  let ((lx, ly), (hx, hy)) = bbox sample in
  bbox (scale 3 sample) = ((3 * lx, 3 * ly), (3 * hx, 3 * hy))
